package pkg;

import haxe.ds.StringMap;

/** A fixture. */
@:keep
class Foo {
	public static inline final LIMIT: Int = 3;

	var count: Int = 0;
	final names: Array<String> = ['b', 'a'];

	public function new() {}

	public function bump(by: Int, label: String): Int {
		count += by;
		trace('bump ' + label);
		return helper(count);
	}

	function helper(x: Int): Int {
		#if debug
		trace(x);
		#end
		return switch x {
			case 0: 1;
			case 1 | 2: x * 2;
			case _: x;
		}
	}

	public function useMap(): StringMap<Int> {
		final m = new StringMap<Int>();
		m.set('k', bump(1, 'k'));
		return m;
	}
}

