class Walk {
	public static function check(dir: String): Void {
		for (f in sys.FileSystem.readDirectory(dir)) {
			if (sys.io.File.getContent('$dir/$f').indexOf('@:registered') < 0) haxe.macro.Context.error('$f registers nothing', haxe.macro.Context.currentPos());
		}
	}
}

